	if (input.referenceNumber) segments.push(createSegment(`Reference number: ${input.referenceNumber}.`, "value"));
	if (input.noticeDate) segments.push(createSegment(`Notice dated ${input.noticeDate}.`, "value"));
	if (input.deadlineDate && input.deadlineUrgencyLabel) {
		const urgencySegment = createSegment(`Response deadline: ${input.deadlineDate}. Urgency level: ${input.deadlineUrgencyLabel}.`, input.deadlineUrgency === "expired" || input.deadlineUrgency === "critical" ? "alert" : "body", {
			priority: input.deadlineUrgency === "expired" || input.deadlineUrgency === "critical" ? "critical" : "high",
			pauseAfter: 800
		});
		segments.push(urgencySegment);
	} else segments.push(createSegment("No response deadline was identified. Verify the deadline manually.", "alert", { priority: "high" }));
	segments.push(createSegment(`Extracted ${input.factCount} fact${input.factCount === 1 ? "" : "s"} from the notice. ${input.confirmedFactCount} confirmed.`, "body"));
	segments.push(createSegment(input.evidenceCount > 0 ? `${input.evidenceCount} evidence item${input.evidenceCount === 1 ? "" : "s"} attached.` : "No evidence has been attached yet.", "body"));
	if (input.findingCount > 0) segments.push(createSegment(`Analysis found ${input.findingCount} issue${input.findingCount === 1 ? "" : "s"} requiring attention.`, "alert", { priority: "high" }));
	if (input.strategyCount > 0) segments.push(createSegment(`${input.strategyCount} response strategy${input.strategyCount === 1 ? "" : "ies"} available.`, "body"));
	if (input.readinessState) {
		const readinessText = input.readinessState === "ready" ? "Your case is ready for response generation." : input.readinessState === "blocked" ? "Your case is blocked. Resolve the blocking issues before proceeding." : input.readinessState === "incomplete" ? "Your case is incomplete. Several items need attention." : input.readinessState === "needs_review" ? "Your case needs review. Please verify the extracted information." : input.readinessState === "urgent" ? "Your case is ready but the deadline is approaching. Act quickly." : "Your case is in draft status.";
		segments.push(createSegment(readinessText, "instruction", { pauseAfter: 600 }));
	}
